__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"privacy",{enumerable:!0,get:function(){return t}});const n=r(d[0]).appConfig.operator,t={id:'privacy',title:'Datenschutzerkl\xe4rung',status:'Stand: 26. November 2026. Entwurf, vor Ver\xf6ffentlichung rechtlich pr\xfcfen lassen.',sections:[{heading:'1. Verantwortlicher',paragraphs:[`${n.name}, Inhaber ${n.owner} (${n.legalForm}), ${n.addressLines.join(', ')}. E-Mail: ${n.email}`,'Die App wird in allen Mitgliedstaaten der Europ\xe4ischen Union angeboten. Der Verantwortliche hat seinen Sitz in Deutschland; es gilt die Datenschutz-Grundverordnung (DSGVO) der EU.']},{heading:'2. Das Wichtigste in K\xfcrze',paragraphs:['Toms Teddy hat kein Konto und keinen eigenen Server. Alles, was in der App gespeichert wird, bleibt auf Ihrem Ger\xe4t.','Wir als Anbieter erhalten keine Daten Ihres Kindes oder von Ihnen: keinen Fortschritt, keine Gef\xfchlsauswahl, keine Einstellungen.','Die App enth\xe4lt keine Werbung, keine Analyse-, Tracking- oder Absturzberichts-Dienste und keine Dienste von Drittanbietern au\xdfer den K\xe4ufen \xfcber den App Store (Apple) bzw. Google Play.','Sie k\xf6nnen alle lokal gespeicherten Daten jederzeit im Bereich f\xfcr Erwachsene unter "Lokale Daten" l\xf6schen.']},{heading:'3. Was auf dem Ger\xe4t gespeichert wird',paragraphs:['Die App speichert folgende Angaben ausschlie\xdflich lokal im Speicher Ihres Ger\xe4ts (in der Web-Demo im Speicher Ihres Browsers):','Fortschritt: welche Einheiten abgeschlossen sind, die zuletzt ge\xf6ffnete Einheit, die freiwillig gew\xe4hlte Gef\xfchlsauswahl je Einheit und gemerkte Lieblingsgeschichten. Die Gef\xfchlsauswahl wird weder ausgewertet noch \xfcbertragen.','Einstellungen: Vorlesen an/aus, Schriftgr\xf6\xdfe, Animationen reduzieren, Erinnerungen an/aus, gew\xe4hlte Hauptfigur (Tom oder Tina), ob die Einf\xfchrung erledigt ist.','Letzter bekannter Kaufstatus (ob ein Abo aktiv ist, bis wann, ob ein Einmalkauf vorliegt), damit gekaufte Inhalte auch ohne Internet verf\xfcgbar bleiben.','Nur in der Web-Demo und in Entwicklungsfassungen: das gew\xe4hlte Demo-Szenario.','Rechtsgrundlage: Art. 6 Abs. 1 lit. b DSGVO (Bereitstellung der von Ihnen genutzten Funktionen). Das Speichern ist f\xfcr diese Funktionen unbedingt erforderlich (\xa7 25 Abs. 2 Nr. 2 TDDDG). Speicherdauer: bis Sie die Daten in der App l\xf6schen oder die App deinstallieren.']},{heading:'4. K\xe4ufe und Abos (nur App f\xfcr iOS und Android)',paragraphs:['K\xe4ufe laufen \xfcber den App Store (Apple) bzw. Google Play (Google). Kauf, Zahlung und Rechnung wickelt der jeweilige Store ab; es gelten dessen Bedingungen und Datenschutzerkl\xe4rungen. Wir erhalten keine Zahlungsdaten, keinen Namen und keine E-Mail-Adresse.','Die App fragt beim Start, bei der R\xfcckkehr in die App und auf Ihren Wunsch ("K\xe4ufe wiederherstellen", "Status erneut pr\xfcfen") beim Store ab, welche Produkte zu Ihrem Store-Konto geh\xf6ren, und erh\xe4lt Produktkennung, Preis, Kaufstatus und Laufzeitangaben des Stores. Daf\xfcr gibt es keinen eigenen Server; es findet keine Weitergabe an Dritte statt.','Rechtsgrundlage: Erf\xfcllung des Kaufvertrags, Art. 6 Abs. 1 lit. b DSGVO. Apple-Datenschutz: https://www.apple.com/de/legal/privacy/de-ww/ . Google-Datenschutz: https://policies.google.com/privacy?hl=de','Ob und auf welcher Grundlage Apple und Google Daten in Drittl\xe4nder \xfcbermitteln, Noch nicht dokumentiert, Pr\xfcfung offen.','Die Web-Demo hat keine echten K\xe4ufe; der Demo-Store l\xe4uft vollst\xe4ndig im Browser.']},{heading:'5. Erinnerungen (nur App f\xfcr iOS und Android)',paragraphs:['Erinnerungen sind standardm\xe4\xdfig aus. Schalten Sie sie ein, fragt das Ger\xe4t erst dann nach der Erlaubnis f\xfcr Mitteilungen und die App plant eine t\xe4gliche Mitteilung auf dem Ger\xe4t. Es gibt keine Push-Kennung und keinen Server. Der Text ist neutral und enth\xe4lt keine Inhalte aus der App. In der Web-Demo gibt es keine Erinnerungen.']},{heading:'6. Vorlesen',paragraphs:['Optional und standardm\xe4\xdfig aus. Die App nutzt die Sprachausgabe Ihres Ger\xe4ts ("Ger\xe4testimme"). In der Web-Demo nutzt der Browser seine eigene Sprachausgabe; je nach Browser und Stimme kann diese einen Online-Dienst des Browser-Herstellers verwenden. Dies steuert der Browser, nicht die App.']},{heading:'7. Links nach au\xdfen',paragraphs:['Externe Links (Hilfsangebote, Abo-Verwaltung im Store, Impressum) gibt es nur im Bereich f\xfcr Erwachsene. Sie werden erst ge\xf6ffnet, wenn Sie sie antippen. Der Kinderbereich enth\xe4lt keine externen Links.']},{heading:'8. Web-Demo',paragraphs:['Die Web-Demo wird \xfcber GitHub Pages (GitHub, Inc., USA) ausgeliefert. Beim Aufruf verarbeitet GitHub technisch notwendige Daten wie die IP-Adresse in Server-Protokollen; Details in der Datenschutzerkl\xe4rung von GitHub. Die Web-Demo setzt keine Cookies und l\xe4dt keine Inhalte von anderen Servern nach. Rechtsgrundlage und Drittland\xfcbermittlung (GitHub): Noch nicht dokumentiert, Pr\xfcfung offen.']},{heading:'9. Backups des Ger\xe4ts',paragraphs:['Hat Ihr Ger\xe4t ein Backup eingeschaltet, kann das Betriebssystem die lokal gespeicherten Daten der App (Abschnitt 3) in Ihr eigenes Konto sichern (iCloud bei Apple, Google-Konto bei Android). Das \xfcbernimmt das Betriebssystem, nicht die App; wir erhalten diese Backups nicht. Sie steuern das in den Systemeinstellungen.']},{heading:'10. Kinder',paragraphs:['Toms Teddy ist f\xfcr das gemeinsame Lesen von Kindern mit einer erwachsenen Person gedacht. Kinder geben keine Texte, Namen oder sonstigen pers\xf6nlichen Daten ein; es gibt keine Konten, keine Freitextfelder und keine Kontaktm\xf6glichkeiten zu Fremden. K\xe4ufe, Links, Einstellungen und Datenl\xf6schung liegen hinter einer Aufgabe, die Erwachsene l\xf6sen (Eltern-Gate).']},{heading:'11. Ihre Rechte',paragraphs:['Sie haben nach der DSGVO das Recht auf Auskunft, Berichtigung, L\xf6schung, Einschr\xe4nkung der Verarbeitung, Daten\xfcbertragbarkeit und Widerspruch sowie das Recht, eine Einwilligung zu widerrufen. Da die App Ihre Daten nicht an uns \xfcbertr\xe4gt, \xfcben Sie die meisten Rechte direkt in der App aus (L\xf6schen unter "Lokale Daten").','Sie haben das Recht, sich bei einer Datenschutz-Aufsichtsbeh\xf6rde zu beschweren (Art. 77 DSGVO), insbesondere in dem EU-Mitgliedstaat Ihres gew\xf6hnlichen Aufenthaltsorts, Ihres Arbeitsplatzes oder des Orts des mutma\xdflichen Versto\xdfes. Eine Liste der Aufsichtsbeh\xf6rden aller EU-Staaten f\xfchrt der Europ\xe4ische Datenschutzausschuss: https://www.edpb.europa.eu/about-edpb/about-edpb/members_de','Die f\xfcr uns zust\xe4ndige Aufsichtsbeh\xf6rde am Sitz des Verantwortlichen ist: Die Landesbeauftragte f\xfcr den Datenschutz Niedersachsen, Postfach 221, 30002 Hannover, https://www.lfd.niedersachsen.de']},{heading:'12. \xc4nderungen',paragraphs:['Wir passen diese Erkl\xe4rung an, wenn sich die App \xe4ndert. Stand: 26. November 2026.']}]}},798,[795]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return t}});var n=r(d[0]);const t={id:'terms',title:'Nutzungsbedingungen',status:'Entwurf, Stand 25. November 2026. Vor Ver\xf6ffentlichung rechtlich pr\xfcfen lassen. Nicht verbindlich.',sections:[{heading:'1. Anbieter und Gegenstand',paragraphs:[`Anbieter ist ${n.appConfig.operator.name}, Inhaber ${n.appConfig.operator.owner}. Toms Teddy ist eine App mit Geschichten und Mitmach-Impulsen zum gemeinsamen Lesen von Kindern und erwachsenen Bezugspersonen, die das Vermissen eines Kuscheltiers behandeln.`]},{heading:'2. Keine Therapie, keine Beratung',paragraphs:['Die App ist keine Therapie, keine Diagnostik und kein medizinisches Produkt. Sie ersetzt keine pers\xf6nliche Hilfe. Bei starker Belastung eines Kindes holen Sie bitte vertraute Menschen oder Fachleute dazu; bei Gefahr den Notruf 112.']},{heading:'3. Nutzung durch Kinder',paragraphs:['Die App ist f\xfcr die Nutzung gemeinsam mit einer erwachsenen Person gedacht. K\xe4ufe, Einstellungen und rechtliche Seiten sind Erwachsenen vorbehalten und durch eine Aufgabe gesch\xfctzt.']},{heading:'4. Kostenlose Basis und Premium',paragraphs:['Die Einheiten 1 bis 10 sind dauerhaft kostenlos. Weitere Einheiten sind mit Premium verf\xfcgbar: als Abo (Monat oder Woche, automatische Verl\xe4ngerung bis zur K\xfcndigung) oder als Einmalkauf.','Preise, Testzeitr\xe4ume, Aktionen und Abrechnungsintervalle zeigt der Store (App Store oder Google Play) vor der Best\xe4tigung. Der Vertrag \xfcber den Kauf kommt \xfcber den Store zustande; es gelten zus\xe4tzlich dessen Bedingungen.','Abos k\xfcndigen Sie jederzeit in der Abo-Verwaltung des Stores. Der Zugang bleibt bis zum Ende der bezahlten Laufzeit bestehen. Der Einmalkauf beendet ein laufendes Abo nicht.','K\xe4ufe gelten f\xfcr das Store-Konto der jeweiligen Plattform; es gibt keine plattform\xfcbergreifende Freischaltung.','Widerrufsbelehrung und Erstattung: Noch nicht dokumentiert, rechtliche Pr\xfcfung offen.']},{heading:'5. Inhalte und Rechte',paragraphs:['Texte und Grafiken der App sind urheberrechtlich gesch\xfctzt. Die Nutzung ist auf die private Nutzung in der App beschr\xe4nkt. Die derzeitigen Inhalte sind eine Entwurfsfassung und noch nicht fachlich gepr\xfcft.']},{heading:'6. Verf\xfcgbarkeit und Haftung',paragraphs:['Verf\xfcgbarkeit, Gew\xe4hrleistung und Haftungsbeschr\xe4nkung: Noch nicht dokumentiert, rechtliche Pr\xfcfung offen.']},{heading:'7. \xc4nderungen, anwendbares Recht',paragraphs:['\xc4nderungen der Bedingungen und anwendbares Recht: Noch nicht dokumentiert, rechtliche Pr\xfcfung offen.']}]}},799,[795]);